  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["U5", "U11", "U6", "U7"],
      "pins": ["U5.11", "U5.17", "U11.7", "U6.7", "U7.7"],
      "nets": ["NET0019"],
      "observed": "The ESP32-C3-MINI-1 (U5) has GPIO6 (pin 11) and GPIO10 (pin 17) both connected to net NET0019, which is the shared SO/MISO line from the three MAX31855 thermocouple amplifiers (U11, U6, U7).",
      "expected": "The specification states the SPI bus uses SCK on GPIO5 and MISO on GPIO10, with independent chip-selects on GPIO4/GPIO6/GPIO7. GPIO6 should be a dedicated chip-select output, not tied to the shared MISO net.",
      "evidence": [
        {"source": "spec", "quote": "SPI2 on GPIO5/GPIO10, CS pins GPIO4/6/7"},
        {"source": "schematic", "quote": "GPIO6 11 NET0019 ... GPIO10 17 NET0019 (mcu.kicad_sch)"}
      ],
      "impact": "GPIO6 and GPIO10 are shorted together on the MISO net. The firmware cannot independently drive GPIO6 as a chip-select, and any attempt to toggle it will fight the MISO line, corrupting thermocouple reads and potentially damaging the ESP32 pin drivers.",
      "confidence": 0.6
    }
  ],
  "summary": "The schematic shows GPIO6 and GPIO10 of the ESP32 both tied to the shared MAX31855 SO/MISO net (NET0019), which conflicts with the specified SPI pinout where GPIO6 should be an independent chip-select. This bridged net would prevent correct thermocouple polling."
}

